#include "oa_native_shadow.h"
#include <string.h>
extern GLuint oa_post_program(const char *,const char *);
static const char *vs="#version 300 es\nout vec2 uv;void main(){vec2 p=vec2(float((gl_VertexID<<1)&2),float(gl_VertexID&2));uv=p;gl_Position=vec4(p*2.-1.,0.,1.);}";
/* Active1900/966ca4dd9891f20a: single bilinear compare. Native top-left
 * textureY flips when reading ordinary GL casterdepth storage. */
static const char *fs="#version 300 es\nprecision highp float;precision highp sampler2DShadow;in vec2 uv;uniform sampler2D scene_depth;uniform sampler2DShadow shadow_depth;uniform vec2 depth_ab;uniform vec4 fade;uniform mat4 screen_to_light;out vec4 o;void main(){float z=depth_ab.y/(texture(scene_depth,uv).r-depth_ab.x);vec2 ndc=uv*2.-1.;vec3 q=(screen_to_light*vec4(ndc*z,z,1.)).xyz;vec2 a=clamp(z*fade.xy+fade.zw,0.,1.);float alpha=min(a.x,a.y);float shadow=texture(shadow_depth,vec3(q.x,1.-q.y,q.z));o=vec4(shadow,shadow,shadow,alpha);}";
void oa_native_shadow_close(oa_native_shadow *p){if(p->depth)glDeleteTextures(1,&p->depth);if(p->fbo)glDeleteFramebuffers(1,&p->fbo);if(p->resolve)glDeleteProgram(p->resolve);if(p->vao)glDeleteVertexArrays(1,&p->vao);memset(p,0,sizeof(*p));}
int oa_native_shadow_open(oa_native_shadow *p,int size){memset(p,0,sizeof(*p));if(size<8)return 0;p->resolution=size;p->resolve=oa_post_program(vs,fs);if(!p->resolve)goto fail;glGenTextures(1,&p->depth);glBindTexture(GL_TEXTURE_2D,p->depth);glTexImage2D(GL_TEXTURE_2D,0,GL_DEPTH_COMPONENT16,size,size,0,GL_DEPTH_COMPONENT,GL_UNSIGNED_SHORT,0);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_LINEAR);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_LINEAR);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_COMPARE_MODE,GL_COMPARE_REF_TO_TEXTURE);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_COMPARE_FUNC,GL_LEQUAL);glGenFramebuffers(1,&p->fbo);glBindFramebuffer(GL_FRAMEBUFFER,p->fbo);glFramebufferTexture2D(GL_FRAMEBUFFER,GL_DEPTH_ATTACHMENT,GL_TEXTURE_2D,p->depth,0);glDrawBuffers(0,0);glReadBuffer(GL_NONE);if(glCheckFramebufferStatus(GL_FRAMEBUFFER)!=GL_FRAMEBUFFER_COMPLETE)goto fail;glGenVertexArrays(1,&p->vao);glBindFramebuffer(GL_FRAMEBUFFER,0);p->ready=glGetError()==GL_NO_ERROR;if(p->ready)return 1;fail:oa_native_shadow_close(p);glBindFramebuffer(GL_FRAMEBUFFER,0);return 0;}
int oa_native_shadow_update(oa_native_shadow *p,const float vp[16],const float eye[3],const float sun[3],const oa_native_shadow_config *config){oa_native_shadow_config c;if(!p||!p->ready)return 0;if(config)c=*config;else oa_native_shadow_defaults(&c);c.resolution=p->resolution;return oa_native_shadow_parameters(p->cascade,p->depth_ab,vp,eye,sun,&c);}
void oa_native_shadow_begin(oa_native_shadow *p,int i){if(!p||!p->ready||i<0||i>=3)return;glBindFramebuffer(GL_FRAMEBUFFER,p->fbo);glViewport(0,0,p->resolution,p->resolution);glColorMask(GL_FALSE,GL_FALSE,GL_FALSE,GL_FALSE);glEnable(GL_DEPTH_TEST);glDepthFunc(GL_LEQUAL);glDepthMask(GL_TRUE);glDisable(GL_BLEND);glDisable(GL_SCISSOR_TEST);glDisable(GL_POLYGON_OFFSET_FILL);glEnable(GL_CULL_FACE);glCullFace(GL_BACK);glFrontFace(GL_CCW);glClearDepthf(1);glClear(GL_DEPTH_BUFFER_BIT);}
void oa_native_shadow_resolve(oa_native_shadow *p,int i,GLuint scene,GLuint target,int w,int h){if(!p||!p->ready||i<0||i>=3)return;glBindFramebuffer(GL_FRAMEBUFFER,target);glViewport(0,0,w,h);glDisable(GL_DEPTH_TEST);glDepthMask(GL_FALSE);glDisable(GL_CULL_FACE);glDisable(GL_SCISSOR_TEST);glDisable(GL_DITHER);glEnable(GL_BLEND);glBlendEquation(GL_FUNC_ADD);glBlendFunc(GL_SRC_ALPHA,GL_ONE_MINUS_SRC_ALPHA);glColorMask(GL_FALSE,GL_TRUE,GL_FALSE,GL_FALSE);glUseProgram(p->resolve);glUniform2fv(glGetUniformLocation(p->resolve,"depth_ab"),1,p->depth_ab);glUniform4fv(glGetUniformLocation(p->resolve,"fade"),1,p->cascade[i].fade);glUniformMatrix4fv(glGetUniformLocation(p->resolve,"screen_to_light"),1,GL_FALSE,p->cascade[i].screen_to_light);glActiveTexture(GL_TEXTURE0);glBindTexture(GL_TEXTURE_2D,scene);glUniform1i(glGetUniformLocation(p->resolve,"scene_depth"),0);glActiveTexture(GL_TEXTURE1);glBindTexture(GL_TEXTURE_2D,p->depth);glUniform1i(glGetUniformLocation(p->resolve,"shadow_depth"),1);glBindVertexArray(p->vao);glDrawArrays(GL_TRIANGLES,0,3);glDisable(GL_BLEND);glColorMask(GL_TRUE,GL_TRUE,GL_TRUE,GL_TRUE);}
